def process_words(text):
    words = text.split()
    result = []
    vowels = {'a', 'e', 'i', 'o', 'u'}

    for word in words:
        if len(word) % 3 == 0:
            result.append(word[::-1])
        elif word[0] in vowels:
            result.append(word.upper())
        else:
            result.append(word)

    return '|'.join(result)
```

