def process_words(text):
    if not text:
        return ''

    words = text.split(' ')
    processed = []

    for word in words:
        if not word:
            continue

        if len(word) % 2 == 0:
            processed.append(word[::-1])
        elif word[0] in 'aeiou':
            processed.append(word.upper())
        else:
            processed.append(word)

    return '_'.join(processed)
```

