def count_paths(grid):
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])

    # dp[i][j][rem] = number of paths from (0,0) to (i,j) with sum % rem == 0
    # rem is 0, 1, or 2
    dp = [[[0] * 3 for _ in range(cols)] for _ in range(rows)]

    # Base case: start cell
    start_val = grid[0][0] % 3
    dp[0][0][start_val] = 1

    # Fill DP table
    for i in range(rows):
        for j in range(cols):
            if i == 0 and j == 0:
                continue

            # From top
            if i > 0:
                rem_top = dp[i-1][j][0] + dp[i-1][j][1] + dp[i-1][j][2]
                if i > 0:
                    for r in range(3):
                        dp[i][j][(r + grid[i][j] % 3) % 3] += dp[i-1][j][r]

            # From left
            if j > 0:
                rem_left = dp[i][j-1][0] + dp[i][j-1][1] + dp[i][j-1][2]
                for r in range(3):
                    dp[i][j][(r + grid[i][j] % 3) % 3] += dp[i][j-1][r]

    return dp[rows-1][cols-1][0]
