def count_paths(grid):
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])

    # dp[r][c] stores the count of paths from (0,0) to (r,c) 
    # whose sum is divisible by 3
    # We also need to track the sum modulo 3 for each cell to know if we can transition

    # Actually, we need to know the sum modulo 3 at each cell to continue the path
    # So dp[r][c][rem] = count of paths from (0,0) to (r,c) with sum % 3 == rem

    dp = [[[0] * 3 for _ in range(cols)] for _ in range(rows)]

    def get_mod_sum(r, c):
        # Calculate sum from (0,0) to (r,c) mod 3
        total = 0
        for i in range(rows):
            for j in range(cols):
                total += grid[i][j]
        return total % 3

    # However, calculating sum for every cell is O(rows*cols), but we can do it incrementally
    # Let's do incremental DP

    # Base case
    dp[0][0][grid[0][0] % 3] = 1

    for r in range(rows):
        for c in range(cols):
            if r == 0 and c == 0:
                continue

            current_val = grid[r][c]
            mod_val = current_val % 3

            # From top
            if r > 0:
                for rem in range(3):
                    if dp[r-1][c][rem] > 0:
                        new_rem = (rem + mod_val) % 3
                        dp[r][c][new_rem] += dp[r-1][c][rem]

            # From left
            if c > 0:
                for rem in range(3):
                    if dp[r][c-1][rem] > 0:
                        new_rem = (rem + mod_val) % 3
                        dp[r][c][new_rem] += dp[r][c-1][rem]

    return dp[rows-1][cols-1][0]
