def count_paths(grid):
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])

    # DP state: dp[r][c] = number of paths from (0,0) to (r,c) with sum % 4 == k
    # Initialize with None
    dp = [[None for _ in range(cols)] for _ in range(rows)]

    def get_mod(val):
        return val % 4

    # Base case: top-left cell
    start_sum = get_mod(grid[0][0])
    dp[0][0] = [0] * 4
    dp[0][0][start_sum] = 1

    # Fill DP table
    for r in range(rows):
        for c in range(cols):
            if r == 0 and c == 0:
                continue

            # Determine possible previous cells
            prev_r, prev_c = -1, -1
            if r > 0:
                prev_r, prev_c = r - 1, c
            if c > 0:
                prev_r, prev_c = r, c - 1

            prev_sum_mod = -1
            if prev_r != -1:
                prev_sum_mod = get_mod(dp[prev_r][prev_c][prev_sum_mod])
            if prev_c != -1:
                prev_sum_mod = get_mod(dp[prev_r][prev_c][prev_sum_mod])

            # Correct approach: check previous valid states
            if r > 0:
                if dp[prev_r][prev_c] is not None:
                    for k in range(4):
                        if dp[prev_r][prev_c][k] > 0:
                            new_k = (k + get_mod(grid[r][c])) % 4
                            dp[r][c][new_k] += dp[prev_r][prev_c][k]
            if c > 0:
                if dp[r][prev_c] is not None:
                    for k in range(4):
                        if dp[r][prev_c][k] > 0:
                            new_k = (k + get_mod(grid[r][c])) % 4
                            dp[r][c][new_k] += dp[r][prev_c][k]

