    if grid[0][0] % 4 == 0:
        dp[0][0] = 1

    # Fill first row
    for c in range(1, cols):
        if grid[0][c] % 4 == 0:
            if dp[0][c-1] > 0:
                dp[0][c] = dp[0][c-1]
        else:
            dp[0][c] = 0

    # Fill first column
    for r in range(1, rows):
        if grid[r][0] % 4 == 0:
            if dp[r-1][0] > 0:
                dp[r][0] = dp[r-1][0]
        else:
            dp[r][0] = 0

    # Fill the rest of the grid
    for r in range(1, rows):
        for c in range(1, cols):
            if (grid[r][c] + dp[r-1][c] + dp[r][c-1]) % 4 == 0:
                dp[r][c] = dp[r-1][c] + dp[r][c-1]
            else:
                dp[r][c] = 0

