def bfs_order(n, edges):
    adj = {i: [] for i in range(n)}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    for node in adj:
        adj[node].sort()

    queue = [0]
    visited = {0}
    result = [0]

    head = 0
    while head < len(queue):
        node = queue[head]
        head += 1

        for neighbor in adj[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
                result.append(neighbor)

    return result
