```python
def bfs_order(n, edges):
    adj = {i: [] for i in range(n)}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    result = []
    visited = set()
    queue = [0]
    visited.add(0)

    while queue:
        node = queue.pop(0)
        result.append(node)

        neighbors = sorted(adj[node], reverse=True)
        for neighbor in neighbors:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

    return result
```
